export const SCRIPT_LINES = {
  "tut_hello_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Beaming welcome, as if greeting the first customer of the day.","text":{"en":"Hello, and welcome to Lane Authority onboarding! I am your onboarding assistant, and I will be with you every step of the way. Every single step.","es":"¡Hola, y bienvenido a la inducción de la Autoridad de Rutas! Soy tu asistente de inducción y estaré contigo en cada paso del camino. En cada uno de ellos.","zh":"你好，欢迎参加航道管理局入职培训！我是你的入职助手，每一步我都会陪着你。真的是每一步哦。"}},
  "tut_contract_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Cheerful legal boilerplate, read fast and proud of it.","text":{"en":"Your contract has been countersigned! Payment is issued on completion of contract. Completion of contract is defined in Appendix F, which is available on request.","es":"¡Tu contrato ya fue firmado por ambas partes! El pago se emite al completar el contrato. La definición de contrato completado está en el Apéndice F, disponible a solicitud.","zh":"你的合同已完成会签！合同完成后即发放报酬。“合同完成”的定义见附录F，可应要求提供。"}},
  "tut_move_000": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Kindergarten-teacher patience, explaining the obvious with great care.","text":{"en":"Let's start with movement! Movement is how you get from one place to another. Please fly to the left.","es":"¡Empecemos con el movimiento! El movimiento es lo que te lleva de un lugar a otro. Por favor, vuela hacia la izquierda.","zh":"我们先从移动开始！移动，就是从一个地方到另一个地方。请向左飞。"}},
  "tut_move_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Maximum cheer, as if this were the most important lesson ever taught; tiny forced giggle at the end.","text":{"en":"Great job pressing the left key! Now, for your next challenge: press the right key. I believe in you. Take all the time you need.","es":"¡Excelente, presionaste la tecla izquierda! Ahora, tu siguiente desafío: presiona la tecla derecha. Creo en ti. Tómate todo el tiempo que necesites.","zh":"太棒了，你按下了左键！接下来，你的下一个挑战是：按下右键。我相信你。慢慢来，不着急。"}},
  "tut_move_002": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Delighted, then a proud little flourish on the last sentence.","text":{"en":"Wonderful! Now up. And now down. You have flown in all four directions. That is every direction we offer.","es":"¡Maravilloso! Ahora hacia arriba. Y ahora hacia abajo. Ya volaste en las cuatro direcciones. Son todas las direcciones que ofrecemos.","zh":"太好了！现在向上。再向下。你已经朝四个方向都飞过了。我们提供的方向就这么多。"}},
  "tut_hitbox_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Sincere and a little tender on the last sentence.","text":{"en":"Your ship is large and beautiful, but only the small glowing gem at its center can be hit. Please protect the gem. The gem is you.","es":"Tu nave es grande y hermosa, pero solo la pequeña gema brillante del centro puede recibir impactos. Por favor, protege la gema. La gema eres tú.","zh":"你的飞船又大又漂亮，但只有中央那颗发光的小宝石会被击中。请保护好宝石。宝石就是你。"}},
  "tut_focus_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Meditation-app calm that keeps slipping back into perkiness.","text":{"en":"Hold focus to fly slowly and precisely. Focus is for threading the gem between bullets. Let's practice. Focus. Good. Still focusing. Great.","es":"Mantén el enfoque para volar despacio y con precisión. El enfoque sirve para pasar la gema entre las balas. Practiquemos. Enfócate. Bien. Sigue enfocado. Genial.","zh":"按住专注键，就能缓慢而精准地飞行。专注，是为了让宝石从子弹缝隙中穿过。我们来练习一下。专注。很好。继续专注。太棒了。"}},
  "tut_fire_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Excited, like unveiling a birthday present.","text":{"en":"Now, let's learn to fire! Hold fire to release bullets. Bullets go up. Up is where the problems are.","es":"¡Ahora aprendamos a disparar! Mantén presionado disparar para soltar balas. Las balas van hacia arriba. Arriba es donde están los problemas.","zh":"现在来学习射击吧！按住射击键就会发射子弹。子弹向上飞。问题都在上面。"}},
  "tut_fire_002": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Captain Obvious, completely sincere, a careful list.","text":{"en":"Your bullets are cyan. Bullets fired at you are pink. Pink bullets are bad. Gold bullets are also bad. In general, bullets are bad, unless they are yours.","es":"Tus balas son cian. Las balas que te disparan son rosas. Las balas rosas son malas. Las doradas también son malas. En general, las balas son malas, salvo las tuyas.","zh":"你的子弹是青色的。射向你的子弹是粉色的。粉色子弹很危险。金色子弹也很危险。总之，子弹都很危险，除非是你自己的。"}},
  "tut_autofire_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Genuinely helpful, then corporate on the last sentence.","text":{"en":"If holding fire for a long time is uncomfortable, auto-fire is in the accessibility settings. The Lane Authority wants your hands healthy and productive.","es":"Si mantener presionado disparar por mucho tiempo te resulta incómodo, el disparo automático está en los ajustes de accesibilidad. La Autoridad de Rutas quiere tus manos sanas y productivas.","zh":"如果长时间按住射击键让你不舒服，可以在无障碍设置中开启自动射击。航道管理局希望你的双手健康又高效。"}},
  "tut_target_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Game-show reveal.","text":{"en":"Here is a practice target. It is a hologram of a Warden scout. Please destroy the hologram.","es":"Aquí tienes un blanco de práctica. Es un holograma de un explorador del Guardián. Por favor, destruye el holograma.","zh":"这是一个练习靶。它是守望者侦察机的全息影像。请摧毁这个全息影像。"}},
  "tut_target_002": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Proud applause, then a motivational-poster cadence.","text":{"en":"Excellent! Scouts are the Warden's eyes. Every eye you close is one less eye on you.","es":"¡Excelente! Los exploradores son los ojos del Guardián. Cada ojo que cierras es un ojo menos sobre ti.","zh":"太棒了！侦察机是守望者的眼睛。你每关掉一只眼睛，盯着你的眼睛就少一只。"}},
  "tut_lives_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Slow and deliberate counting, like a crossing guard.","text":{"en":"Your hull holds three hits. Each hit also costs one cannon level. Please count to three with me. One. Two. Three.","es":"Tu casco resiste tres impactos. Cada impacto también te cuesta un nivel de cañón. Cuenta conmigo hasta tres. Uno. Dos. Tres.","zh":"你的船体能承受三次命中。每次命中还会让主炮降一级。请跟我一起数到三。一。二。三。"}},
  "tut_continue_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Breezy reassurance; the last sentence is meant kindly and lands badly.","text":{"en":"And if you run out of hull, don't worry! The Lane Authority will requisition a new ship, and onboarding will continue. You will hardly notice.","es":"Y si te quedas sin casco, ¡no te preocupes! La Autoridad de Rutas requisará una nave nueva y la inducción continuará. Casi ni lo notarás.","zh":"就算船体耗尽，也别担心！航道管理局会调拨一艘新飞船，入职培训会继续进行。你几乎察觉不到。"}},
  "tut_pickup_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Product-demo enthusiasm, then fine print read slightly faster.","text":{"en":"Pickups! Green crystals widen your spread. Cyan diamonds grant a shield. Pickups are recovered salvage and remain Lane Authority property.","es":"¡Objetos! Los cristales verdes amplían tu disparo. Los diamantes cian te dan un escudo. Los objetos son material recuperado y siguen siendo propiedad de la Autoridad de Rutas.","zh":"道具！绿色水晶能扩大射击范围。青色菱形能提供护盾。道具均为回收物资，仍归航道管理局所有。"}},
  "tut_wink_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Conspiratorial little aside, then brightly back on message.","text":{"en":"Fun fact! An independent review rated this onboarding thorough. It also rated it long. We have chosen to focus on thorough.","es":"¡Dato curioso! Una evaluación independiente calificó esta inducción como exhaustiva. También la calificó como larga. Decidimos quedarnos con exhaustiva.","zh":"冷知识！一项独立评估认为这次入职培训很全面。它还认为培训很长。我们决定只看“全面”这一条。"}},
  "tut_review_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Quiz-show host answering her own questions without a pause.","text":{"en":"Quick review! Which bullets are bad? That's right. The pink ones, the gold ones, and, in general, bullets. Which part of the ship can be hit? The gem. You're a natural.","es":"¡Repaso rápido! ¿Qué balas son malas? Así es. Las rosas, las doradas y, en general, las balas. ¿Qué parte de la nave puede recibir impactos? La gema. Tienes talento nato.","zh":"快速复习！哪些子弹危险？没错。粉色的、金色的，总之，子弹。飞船哪个部位会被击中？宝石。你真是天生的飞行员。"}},
  "tut_route_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Tour-guide list, slowing and dropping into a hush on the last words.","text":{"en":"Your route: Outer Drift. Shatter Belt. Gun Lanes. Lancer Gate. Last Approach. And then...","es":"Tu ruta: Deriva Exterior. Cinturón Quebrado. Rutas de Artillería. Puerta de los Lanceros. Aproximación Final. Y luego...","zh":"你的航线：外缘漂流带。碎裂带。炮火航道。枪骑之门。最终进近。然后……"}},
  "tut_warden_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"A theatrical gulp, then flight-attendant brightness.","text":{"en":"And then, the Warden. Before we continue, the Lane Authority requires you to watch a short threat briefing. Please enjoy it.","es":"Y luego, el Guardián. Antes de continuar, la Autoridad de Rutas requiere que veas una breve sesión informativa sobre amenazas. Disfrútala.","zh":"然后，就是守望者。继续之前，航道管理局要求你观看一段简短的威胁简报。请欣赏。"}},
  "brief_warden_001": {"speaker":"narrator","scene":"tutorial","route":"any","optional":false,"direction":"Trailer cold open over a black screen. Slow, low, enormous.","text":{"en":"In the deepest lanes of the nebula, something waits.","es":"En las rutas más profundas de la nebulosa, algo espera.","zh":"在星云最深处的航道里，有什么东西在等待。"}},
  "brief_warden_002": {"speaker":"narrator","scene":"tutorial","route":"any","optional":false,"direction":"Each sentence its own beat; let the title land like a door slamming.","text":{"en":"It has no name. Only a title. The Warden.","es":"No tiene nombre. Solo un título. El Guardián.","zh":"它没有名字。只有一个称号。守望者。"}},
  "brief_warden_003": {"speaker":"narrator","scene":"tutorial","route":"any","optional":false,"direction":"Grave statistics, a long pause before the last sentence.","text":{"en":"For three hundred years it has held the lanes shut. One hundred and twenty-one pilots have flown against it. None came back.","es":"Durante trescientos años ha mantenido cerradas las rutas. Ciento veintiún pilotos han volado contra él. Ninguno regresó.","zh":"三百年来，它一直封锁着航道。一百二十一名飞行员向它发起过挑战。没有一个回来。"}},
  "brief_warden_004": {"speaker":"narrator","scene":"tutorial","route":"any","optional":false,"direction":"Hushed dread, as if afraid it might hear.","text":{"en":"Its voice alone has cracked hulls. Those who have heard it never forget it.","es":"Su voz, por sí sola, ha agrietado cascos. Quienes la han oído jamás la olvidan.","zh":"单是它的声音，就能震裂船体。听过的人，永远不会忘记。"}},
  "brief_warden_005": {"speaker":"narrator","scene":"tutorial","route":"any","optional":false,"direction":"Same doom, but the stakes are commercial; play it with no irony at all.","text":{"en":"While it stands, no toll can be collected. No route can be licensed. No lane can be owned.","es":"Mientras siga en pie, no se puede cobrar ningún peaje. Ninguna ruta puede concesionarse. Ninguna ruta puede tener dueño.","zh":"只要它还在，就收不了一分通行费。航道无法授权经营。航道无法归任何人所有。"}},
  "brief_warden_006": {"speaker":"narrator","scene":"tutorial","route":"any","optional":false,"direction":"Triumphant brand tag, then the disclaimer in the same grave voice.","text":{"en":"The Lane Authority. Opening the lanes, for everyone. Terms and conditions apply.","es":"La Autoridad de Rutas. Abriendo las rutas para todos. Aplican términos y condiciones.","zh":"航道管理局。为所有人开放航道。适用相关条款与条件。"}},
  "tut_warden_002": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Breathless from the reel, then soothing customer service.","text":{"en":"Wasn't that exciting? Please don't be frightened. Fear is not covered by your contract.","es":"¿Verdad que fue emocionante? Por favor, no te asustes. El miedo no está cubierto por tu contrato.","zh":"是不是很激动人心？请不要害怕。你的合同不涵盖恐惧。"}},
  "tut_done_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Graduation-day pride; the last sentence is a catchphrase.","text":{"en":"Onboarding complete! Your contract is now active. Please proceed to Outer Drift. And remember: stay in your lane, Pilot.","es":"¡Inducción completada! Tu contrato ya está activo. Por favor, dirígete a la Deriva Exterior. Y recuerda: no te salgas de tu ruta, piloto.","zh":"入职培训完成！你的合同现已生效。请前往外缘漂流带。记住：别偏离你的航道，飞行员。"}},
  "tut_idle_001": {"speaker":"tutorial_ai","scene":"tutorial","route":"any","optional":false,"direction":"Patient, with a stopwatch audible in the smile.","text":{"en":"Take all the time you need. I am timing it, but take all the time you need.","es":"Tómate todo el tiempo que necesites. Lo estoy cronometrando, pero tómate todo el tiempo que necesites.","zh":"慢慢来，不着急。我在计时，但你慢慢来。"}},
  "tut_skip_001": {"speaker":"tutorial_ai","scene":"tutorial_skip","route":"any","optional":false,"direction":"Surprised, a little wounded, recovering fast.","text":{"en":"Oh! You'd like to skip onboarding? That's completely fine. Onboarding is just where we become friends.","es":"¡Oh! ¿Quieres saltarte la inducción? No pasa nada. La inducción es solo donde nos hacemos amigos.","zh":"哦！你想跳过入职培训？完全没问题。入职培训只是我们成为朋友的地方而已。"}},
  "tut_skip_002": {"speaker":"tutorial_ai","scene":"tutorial_skip","route":"any","optional":false,"direction":"Reading a log entry aloud, then brave and bright.","text":{"en":"Logged as: declined onboarding. That's okay. I will be on comms the whole time anyway.","es":"Registrado como: rechazó la inducción. Está bien. De todos modos estaré en la radio todo el tiempo.","zh":"已记录：拒绝入职培训。没关系。反正我会一直在通讯频道里。"}},
  "sec1_intro_001": {"speaker":"tutorial_ai","scene":"sector1","route":"any","optional":false,"direction":"On comms, crisp mission-control energy.","text":{"en":"Outer Drift. Scouts ahead. Scout fire is light, and completely unprovoked.","es":"Deriva Exterior. Exploradores al frente. Su fuego es ligero y totalmente sin provocación.","zh":"外缘漂流带。前方有侦察机。侦察机火力很弱，而且完全是无端挑衅。"}},
  "sec2_intro_001": {"speaker":"tutorial_ai","scene":"sector2","route":"any","optional":false,"direction":"On comms, trivia-night sparkle.","text":{"en":"Shatter Belt. Divers incoming. Did you know? Darts used to carry guns, until a treaty disarmed them. We did not sign it.","es":"Cinturón Quebrado. Se acercan los picadores. ¿Sabías que los dardos antes llevaban armas, hasta que un tratado los desarmó? Nosotros no lo firmamos.","zh":"碎裂带。俯冲机来袭。你知道吗？飞镖机以前是带武器的，后来一项条约解除了它们的武装。我们没有签那项条约。"}},
  "sec3_intro_001": {"speaker":"tutorial_ai","scene":"sector3","route":"any","optional":false,"direction":"On comms, mildly scandalized by the waste.","text":{"en":"Gun Lanes. Turrets online. These lanes were built for free passage, three centuries ago. No tollgates anywhere. Very inefficient.","es":"Rutas de Artillería. Torretas activas. Estas rutas se construyeron para el paso libre, hace tres siglos. Ni una caseta de peaje. Muy ineficiente.","zh":"炮火航道。炮塔已上线。这些航道是三个世纪前为自由通行而建的。一个收费站都没有。效率太低了。"}},
  "sec4_intro_001": {"speaker":"tutorial_ai","scene":"sector4","route":"any","optional":false,"direction":"On comms, briefing voice that trails off into honest puzzlement.","text":{"en":"Lancer Gate. Crossfire. Lancers fire across the lane, never along it. Almost as if they were keeping the lane itself clear. Odd.","es":"Puerta de los Lanceros. Fuego cruzado. Los lanceros disparan a través de la ruta, nunca a lo largo. Casi como si mantuvieran la ruta despejada. Qué raro.","zh":"枪骑之门。交叉火力。枪骑机总是横穿航道开火，从不沿着航道。简直像是在让航道本身保持畅通。奇怪。"}},
  "sec5_intro_001": {"speaker":"tutorial_ai","scene":"sector5","route":"any","optional":false,"direction":"On comms, quarterly-earnings-call triumph.","text":{"en":"Last Approach. Everything they have. Analysts say the Warden is down to its last reserves. This is what a winning quarter looks like!","es":"Aproximación Final. Todo lo que tienen. Los analistas dicen que al Guardián le quedan sus últimas reservas. ¡Así se ve un trimestre ganador!","zh":"最终进近。倾巢而出。分析师说，守望者已经动用最后的储备了。这就是一个盈利季度该有的样子！"}},
  "amb_fight_001": {"speaker":"tutorial_ai","scene":"chatter","route":"kill","optional":false,"direction":"On comms, warm performance-review praise.","text":{"en":"Every scout you clear is logged to your performance record. Your record looks wonderful.","es":"Cada explorador que eliminas queda en tu registro de desempeño. Tu registro se ve maravilloso.","zh":"你清除的每一架侦察机都会记入你的绩效档案。你的档案看起来棒极了。"}},
  "amb_fight_003": {"speaker":"tutorial_ai","scene":"chatter","route":"kill","optional":false,"direction":"On comms, encouraging, unaware of how it sounds.","text":{"en":"You're doing great. Your predecessor was also doing great at this point.","es":"Lo estás haciendo genial. Tu predecesor también lo estaba haciendo genial en este punto.","zh":"你表现得很好。你的前任在这个阶段也表现得很好。"}},
  "amb_fight_004": {"speaker":"tutorial_ai","scene":"chatter","route":"any","optional":false,"direction":"On comms, gentle policy reminder.","text":{"en":"Reminder: pickups are Lane Authority property. Please don't get attached.","es":"Recordatorio: los objetos son propiedad de la Autoridad de Rutas. Por favor, no te encariñes.","zh":"提醒一下：道具归航道管理局所有。请不要对它们产生感情。"}},
  "amb_fight_005": {"speaker":"tutorial_ai","scene":"chatter","route":"any","optional":false,"direction":"On comms, breezy, as if about litter.","text":{"en":"If you see unarmed ships in the lanes, please ignore them. They are not paying customers yet.","es":"Si ves naves desarmadas en las rutas, por favor ignóralas. Todavía no son clientes de pago.","zh":"如果你在航道里看到没有武装的船，请无视它们。它们还不是付费客户。"}},
  "amb_nofire_001": {"speaker":"tutorial_ai","scene":"chatter","route":"pacifist","optional":false,"direction":"On comms, tech-support concern.","text":{"en":"Pilot, your weapon logs show no activity. Is your trigger working? Please fire.","es":"Piloto, tu registro de armas no muestra actividad. ¿Funciona tu gatillo? Por favor, dispara.","zh":"飞行员，你的武器日志显示没有任何开火记录。扳机正常吗？请射击。"}},
  "amb_nofire_002": {"speaker":"tutorial_ai","scene":"chatter","route":"pacifist","optional":false,"direction":"On comms, carefully neutral, which is not neutral.","text":{"en":"Your weapon is still cold. I am noting that. Neutrally.","es":"Tu arma sigue fría. Lo estoy anotando. De forma neutral.","zh":"你的武器还是冷的。我记下了。客观地记下了。"}},
  "amb_nofire_003": {"speaker":"tutorial_ai","scene":"chatter","route":"pacifist","optional":false,"direction":"On comms, genuinely confused, reading her notes.","text":{"en":"The scouts are not firing at you. That is not in my briefing.","es":"Los exploradores no te están disparando. Eso no está en mi sesión informativa.","zh":"侦察机没有向你开火。简报里可没写这个。"}},
  "amb_nofire_004": {"speaker":"tutorial_ai","scene":"chatter","route":"pacifist","optional":false,"direction":"On comms, HR voice: soft words, firm meaning.","text":{"en":"Non-performance is a serious contract matter. I'm only saying that because I care.","es":"El no desempeño es un asunto contractual serio. Solo lo digo porque me importas.","zh":"未履约是严重的合同问题。我这么说，只是因为我关心你。"}},
  "bark_lifelost_001": {"speaker":"tutorial_ai","scene":"barks","route":"any","optional":false,"direction":"On comms, quick and chipper damage report.","text":{"en":"Hull breach! You're fine. The ship isn't, but you're fine.","es":"¡Brecha en el casco! Tú estás bien. La nave no, pero tú estás bien.","zh":"船体破损！你没事。飞船有事，但你没事。"}},
  "bark_shield_001": {"speaker":"tutorial_ai","scene":"barks","route":"any","optional":false,"direction":"On comms, product-safety notice.","text":{"en":"Shield online! It is Authority property, so please get hit as little as possible.","es":"¡Escudo activo! Es propiedad de la Autoridad, así que, por favor, recibe la menor cantidad de impactos posible.","zh":"护盾已上线！它归管理局所有，所以请尽量少挨打。"}},
  "bark_gameover_001": {"speaker":"tutorial_ai","scene":"barks","route":"any","optional":false,"direction":"On comms, routine procedure, not unkind.","text":{"en":"Ship lost. The lanes stay closed, for now. Requisitioning a replacement.","es":"Nave perdida. Las rutas siguen cerradas, por ahora. Requisando un reemplazo.","zh":"飞船损毁。航道依旧封闭，暂时如此。正在调拨替代者。"}},
  "flash_ai_001": {"speaker":"tutorial_ai","scene":"flashback","route":"any","optional":false,"direction":"Rising alarm under the customer-service smile, faster each sentence.","text":{"en":"Oh! That crystal is a recovered flight recorder. Please don't open it. You're opening it. It's opening.","es":"¡Oh! Ese cristal es una grabadora de vuelo recuperada. Por favor, no la abras. La estás abriendo. Se está abriendo.","zh":"哦！那块水晶是一个回收的飞行记录仪。请不要打开它。你在打开它。它打开了。"}},
  "flash_rec_001": {"speaker":"tutorial_ai","scene":"flashback","route":"any","optional":false,"direction":"Recorded log header, flatter and older than her present self.","text":{"en":"Recording. Pilot zero one two one. Last Approach. Weapon status: cold.","es":"Grabando. Piloto cero uno dos uno. Aproximación Final. Estado del arma: fría.","zh":"记录中。零一二一号飞行员。最终进近。武器状态：未开火。"}},
  "flash_rec_002": {"speaker":"tutorial_ai","scene":"flashback","route":"any","optional":false,"direction":"Recorded; the script breaks down into pleading on the last word.","text":{"en":"Pilot zero one two one, your weapon is cold. Please fire. Please fire. Pilot, please.","es":"Piloto cero uno dos uno, tu arma está fría. Por favor, dispara. Por favor, dispara. Piloto, por favor.","zh":"零一二一号飞行员，你的武器没有开火。请射击。请射击。飞行员，拜托了。"}},
  "flash_rec_003": {"speaker":"warden","scene":"flashback","route":"any","optional":false,"direction":"Recorded, shrill astonishment, almost offended that someone stopped.","text":{"en":"You stopped! Why did you stop?! Nobody stops! Nobody EVER stops!","es":"¡Te detuviste! ¿¡Por qué te detuviste!? ¡Nadie se detiene! ¡Nadie se detiene NUNCA!","zh":"你停下了！你为什么停下了？！没人会停下！从来没人停下过！"}},
  "flash_rec_004": {"speaker":"warden","scene":"flashback","route":"any","optional":false,"direction":"Recorded, furious joy, showing off something precious.","text":{"en":"Look! The little ships! No guns! They fly my lanes because I keep them free! FREE! Do you know what free means?!","es":"¡Mira! ¡Las navecitas! ¡Sin armas! ¡Vuelan por mis rutas porque yo las mantengo libres! ¡LIBRES! ¿¡Sabes lo que significa libre!?","zh":"看！那些小船！没有武器！它们能在我的航道上飞，是因为我让航道保持自由！自由！你知道自由是什么意思吗？！"}},
  "flash_rec_005": {"speaker":"tutorial_ai","scene":"flashback","route":"any","optional":false,"direction":"Recorded, procedural and polite, as if closing a support ticket.","text":{"en":"Non-performance confirmed. Pilot zero one two one, recall initiated. Thank you for your service.","es":"No desempeño confirmado. Piloto cero uno dos uno, retiro iniciado. Gracias por tus servicios.","zh":"确认未履约。零一二一号飞行员，召回程序已启动。感谢你的服务。"}},
  "flash_rec_006": {"speaker":"warden","scene":"flashback","route":"any","optional":false,"direction":"Recorded, the high voice cracking into a scream as the signal cuts.","text":{"en":"No. No, no, no! Don't you take him! He STOPPED!","es":"No. ¡No, no, no! ¡No te lo lleves! ¡Él se DETUVO!","zh":"不。不，不，不！别把他带走！他已经停手了！"}},
  "flash_ai_002": {"speaker":"tutorial_ai","scene":"flashback","route":"any","optional":false,"direction":"Present day, a beat too quick and too bright; the serial is the reveal.","text":{"en":"That recording was corrupted. Please disregard it. Welcome back, Pilot zero one two two.","es":"Esa grabación estaba dañada. Por favor, ignórala. Bienvenido de nuevo, piloto cero uno dos dos.","zh":"那段记录已损坏，请忽略。欢迎回来，零一二二号飞行员。"}},
  "flash_ai_003": {"speaker":"tutorial_ai","scene":"flashback","route":"any","optional":false,"direction":"Aggressively normal, changing the subject.","text":{"en":"Spread shot equipped! Isn't it pretty?","es":"¡Disparo amplio equipado! ¿Verdad que es bonito?","zh":"散射弹已装备！是不是很漂亮？"}},
  "warn_ai_001": {"speaker":"tutorial_ai","scene":"warden_descent","route":"any","optional":false,"direction":"On comms, trying hard to sound brave.","text":{"en":"Warning. The Warden approaches. This is it, Pilot. Everything we trained for. Remember the briefing.","es":"Advertencia. Se acerca el Guardián. Llegó la hora, piloto. Todo aquello para lo que entrenamos. Recuerda la sesión informativa.","zh":"警告。守望者正在接近。就是现在，飞行员。我们训练的一切都为了这一刻。记住简报。"}},
  "warn_narr_001": {"speaker":"narrator","scene":"warden_descent","route":"any","optional":false,"direction":"The biggest, lowest, slowest two words in the game.","text":{"en":"The Warden.","es":"El Guardián.","zh":"守望者。"}},
  "desc_001": {"speaker":"warden","scene":"warden_descent","route":"any","optional":false,"direction":"First words ever heard from the Warden: high, shrill, indignant. The joke is that it is not the briefing voice.","text":{"en":"STOP! Stop right there! Do you have ANY idea how long it takes to grow a scout?!","es":"¡ALTO! ¡Alto ahí! ¿¡Tienes la MÁS MÍNIMA idea de cuánto tarda en crecer un explorador!?","zh":"站住！给我站住！你知不知道培育一架侦察机要多久？！"}},
  "desc_ai_001": {"speaker":"tutorial_ai","scene":"warden_descent","route":"any","optional":false,"direction":"On comms, small and baffled, half to herself.","text":{"en":"That is not the voice from the briefing.","es":"Esa no es la voz de la sesión informativa.","zh":"这和简报里的声音不一样。"}},
  "desc_002": {"speaker":"warden","scene":"warden_descent","route":"kill","optional":false,"direction":"Exasperated list, each item louder.","text":{"en":"Every cycle they send another one! Shiny ship! Big gun! NO MANNERS!","es":"¡Cada ciclo mandan a otro! ¡Nave reluciente! ¡Arma enorme! ¡CERO MODALES!","zh":"每个周期他们都派一个来！亮闪闪的飞船！大炮！毫无礼貌！"}},
  "desc_003": {"speaker":"warden","scene":"warden_descent","route":"any","optional":false,"direction":"Grand proclamation that collapses into weariness.","text":{"en":"I am the Warden! I keep these lanes! And I am SO TIRED of saying that!","es":"¡Soy el Guardián! ¡Yo cuido estas rutas! ¡Y estoy TAN CANSADO de repetirlo!","zh":"我是守望者！我守护这些航道！我真的说烦了！"}},
  "desc_004": {"speaker":"warden","scene":"warden_descent","route":"kill","optional":false,"direction":"A furious final warning, pointing at the gun.","text":{"en":"Turn around. Go home. With that gun, the lanes stay closed!","es":"Da la vuelta. Vete a casa. ¡Con esa arma, las rutas siguen cerradas!","zh":"掉头。回家去。带着那把枪，航道依旧封闭！"}},
  "desc_pac_001": {"speaker":"warden","scene":"warden_descent","route":"pacifist","optional":false,"direction":"Sudden suspicion, rapid-fire.","text":{"en":"Wait. Wait, wait, wait. Your gun is cold. Why is your gun cold?!","es":"Espera. Espera, espera, espera. Tu arma está fría. ¿¡Por qué tu arma está fría!?","zh":"等等。等等等等。你的枪是冷的。你的枪为什么是冷的？！"}},
  "desc_pac_002": {"speaker":"warden","scene":"warden_descent","route":"pacifist","optional":false,"direction":"Realization; the shout drains out of the voice for once.","text":{"en":"The last cold gun was zero one two one. Oh. Oh, no. You're the next number.","es":"La última arma fría fue la de cero uno dos uno. Oh. Oh, no. Eres el siguiente número.","zh":"上一把冷枪，是零一二一号的。哦。哦不。你就是下一个编号。"}},
  "desc_ai_002": {"speaker":"tutorial_ai","scene":"warden_descent","route":"any","optional":false,"direction":"On comms, firmly back on script.","text":{"en":"Proceed with the engagement, Pilot. Statements by the Warden are not covered by your contract.","es":"Procede con el enfrentamiento, piloto. Las declaraciones del Guardián no están cubiertas por tu contrato.","zh":"飞行员，请继续交战。守望者的言论不在你的合同范围内。"}},
  "boss_taunt_001": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Booming, hammy fury; build to a roar on the last sentence, then a short menacing laugh.","text":{"en":"You call that shooting? I have fought toasters with more courage than you! Come closer, little pilot, and meet your final wave!","es":"¿A eso le llamas disparar? ¡He peleado contra tostadoras con más valor que tú! ¡Acércate, pilotito, y conoce tu última oleada!","zh":"你管这叫射击？我打过的烤面包机都比你有胆量！靠近点，小飞行员，迎接你的最后一波吧！"}},
  "boss_p1_002": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Yelp of pain turning into outrage.","text":{"en":"Ow! OW! That was a ring! Do you know how OLD that ring is?!","es":"¡Ay! ¡AY! ¡Eso era un anillo! ¿¡Sabes lo VIEJO que es ese anillo!?","zh":"哎哟！哎哟！那是一个光环！你知道那个光环有多古老吗？！"}},
  "boss_p2_001": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Barking orders at its own scouts, frazzled.","text":{"en":"Scouts, to me! No, not AT him, AROUND him! Protect the lane!","es":"¡Exploradores, conmigo! ¡No, no CONTRA él, ALREDEDOR de él! ¡Protejan la ruta!","zh":"侦察机，过来！不，不是打他，是围着他！保护航道！"}},
  "boss_p2_002": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Wounded pride, nearly a whine.","text":{"en":"You think I WANT to do this? I would rather be counting freighters!","es":"¿¡Crees que QUIERO hacer esto!? ¡Preferiría estar contando cargueros!","zh":"你以为我想这样吗？我宁可去数货船！"}},
  "boss_p3_001": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Turning red: all-in, voice cracking at the top.","text":{"en":"Fine! FINE! Everything I have! EVERYTHING!","es":"¡Bien! ¡BIEN! ¡Todo lo que tengo! ¡TODO!","zh":"好！好啊！我所有的一切！全都给你！"}},
  "boss_p3_002": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Exhausted contempt.","text":{"en":"Three hundred years, and you all bring the same gun!","es":"¡Trescientos años, y todos traen la misma arma!","zh":"三百年了，你们带的都是同一把枪！"}},
  "boss_turn_001": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"The turn: still shouting, but pleading now, not threatening.","text":{"en":"Do you know what's behind me? Nothing! Sky! Free sky, for anyone who comes without a gun!","es":"¿¡Sabes qué hay detrás de mí!? ¡Nada! ¡Cielo! ¡Cielo libre, para cualquiera que venga sin armas!","zh":"你知道我身后是什么吗？什么都没有！只有天空！自由的天空，给每一个不带枪的人！"}},
  "boss_turn_002": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Desperate, spitting the last word.","text":{"en":"They don't want the lanes open! They want them OWNED!","es":"¡Ellos no quieren las rutas abiertas! ¡Las quieren SUYAS!","zh":"他们要的不是开放航道！他们要的是占有航道！"}},
  "boss_turn_003": {"speaker":"warden","scene":"boss","route":"kill","optional":false,"direction":"Grief breaking through the fury.","text":{"en":"Zero one two one stopped! He listened! Why won't YOU listen?!","es":"¡Cero uno dos uno se detuvo! ¡Él escuchó! ¿¡Por qué TÚ no escuchas!?","zh":"零一二一号停手了！他听进去了！你为什么就是不听？！"}},
  "boss_ai_001": {"speaker":"tutorial_ai","scene":"boss","route":"kill","optional":false,"direction":"On comms, cheerleader; she has not heard a word the Warden said.","text":{"en":"Great hit! Your payment is ninety percent vested!","es":"¡Gran impacto! ¡Tu pago ya está consolidado al noventa por ciento!","zh":"漂亮的一击！你的报酬已兑现百分之九十！"}},
  "boss_pac_001": {"speaker":"warden","scene":"boss","route":"pacifist","optional":false,"direction":"Paranoid, high, repeating itself.","text":{"en":"You're not shooting. You are NOT SHOOTING. Is this a trick? Is it a trick?!","es":"No estás disparando. NO ESTÁS DISPARANDO. ¿Es un truco? ¿¡Es un truco!?","zh":"你没开枪。你真的没开枪。这是诡计吗？是诡计吗？！"}},
  "boss_pac_002": {"speaker":"warden","scene":"boss","route":"pacifist","optional":false,"direction":"Duty-bound, almost apologetic, still shouting.","text":{"en":"I still have to test you! Every ship gets tested! So dodge! DODGE!","es":"¡Igual tengo que ponerte a prueba! ¡Toda nave pasa la prueba! ¡Así que esquiva! ¡ESQUIVA!","zh":"我还是得测试你！每艘船都要接受测试！那就躲！快躲！"}},
  "boss_pac_003": {"speaker":"warden","scene":"boss","route":"pacifist","optional":false,"direction":"Delighted cackle, a proud coach.","text":{"en":"Ha! Good! Very good! You fly like a freighter with opinions!","es":"¡Ja! ¡Bien! ¡Muy bien! ¡Vuelas como un carguero con opiniones propias!","zh":"哈！好！很好！你飞得像一艘有主见的货船！"}},
  "boss_pac_ai_001": {"speaker":"tutorial_ai","scene":"boss","route":"pacifist","optional":false,"direction":"On comms, compliance-officer calm.","text":{"en":"Pilot, your weapon shows no activity during a contracted engagement. This has been escalated.","es":"Piloto, tu arma no muestra actividad durante un enfrentamiento contratado. Esto ha sido escalado.","zh":"飞行员，在合同规定的交战中，你的武器没有任何开火记录。此事已上报。"}},
  "boss_pac_ai_002": {"speaker":"tutorial_ai","scene":"boss","route":"pacifist","optional":false,"direction":"On comms, hold-music politeness.","text":{"en":"Recall authorization requested. Please hold. Your call is important to us.","es":"Autorización de retiro solicitada. Por favor, espera. Tu llamada es importante para nosotros.","zh":"已申请召回授权。请稍候。你的来电对我们很重要。"}},
  "kill_warden_001": {"speaker":"warden","scene":"ending_kill","route":"kill","optional":false,"direction":"Dying, the high voice small and almost calm for the first time.","text":{"en":"Oh. Oh, there goes another ring. Count them, zero one two two. Count what they put where the rings were.","es":"Oh. Oh, ahí va otro anillo. Cuéntalos, cero uno dos dos. Cuenta lo que ponen donde estaban los anillos.","zh":"哦。哦，又一个光环熄灭了。数一数，零一二二号。数数他们在光环原来的位置放了什么。"}},
  "kill_ai_001": {"speaker":"tutorial_ai","scene":"ending_kill","route":"kill","optional":false,"direction":"On comms, pure celebration, confetti in the voice.","text":{"en":"Warden down! The lanes are open!","es":"¡Guardián derribado! ¡Las rutas están abiertas!","zh":"守望者已被击落！航道已开放！"}},
  "end_epi_001": {"speaker":"narrator","scene":"ending_kill","route":"kill","optional":false,"direction":"Elegiac, slow, no trailer bombast left.","text":{"en":"The Warden's lights go dark, one ring at a time.","es":"Las luces del Guardián se apagan, un anillo a la vez.","zh":"守望者的光芒熄灭了，一环接着一环。"}},
  "end_epi_002": {"speaker":"narrator","scene":"ending_kill","route":"kill","optional":false,"direction":"Quiet, wide, a breath before it.","text":{"en":"Behind you, five sectors of open sky.","es":"Detrás de ti, cinco sectores de cielo abierto.","zh":"在你身后，是五个星区的开阔天空。"}},
  "kill_ai_002": {"speaker":"tutorial_ai","scene":"ending_kill","route":"kill","optional":false,"direction":"On comms, a service announcement, completely sincere.","text":{"en":"Tollgate deployment has begun. The lanes will be open to all subscribers within the hour.","es":"Comenzó el despliegue de casetas de peaje. Las rutas estarán abiertas para todos los suscriptores en menos de una hora.","zh":"收费站已开始部署。一小时内，航道将向所有订阅用户开放。"}},
  "end_epi_003": {"speaker":"narrator","scene":"ending","route":"any","optional":false,"direction":"The last line of the original game. Let it hang.","text":{"en":"Ahead, the long way home.","es":"Por delante, el largo camino a casa.","zh":"前方，是漫长的归途。"}},
  "kill_ai_003": {"speaker":"tutorial_ai","scene":"ending_kill","route":"kill","optional":false,"direction":"On comms, warm and proud, then the payroll fine print at speed.","text":{"en":"Congratulations, Pilot zero one two two. Your contract is complete. Payment will be issued in thirty to ninety business days.","es":"Felicidades, piloto cero uno dos dos. Tu contrato está completo. El pago se emitirá en un plazo de treinta a noventa días hábiles.","zh":"恭喜你，零一二二号飞行员。你的合同已完成。报酬将在三十至九十个工作日内发放。"}},
  "kill_ai_004": {"speaker":"tutorial_ai","scene":"ending_kill","route":"kill","optional":false,"direction":"Same warmth, meant as good news. No irony.","text":{"en":"Your replacement is already in onboarding.","es":"Tu reemplazo ya está en inducción.","zh":"你的接替者已经在接受入职培训了。"}},
  "pac_end_001": {"speaker":"warden","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"Awed, still loud, voice wobbling.","text":{"en":"You dodged everything. Everything! And you never fired back. Not once.","es":"Esquivaste todo. ¡Todo! Y nunca devolviste el fuego. Ni una vez.","zh":"你躲开了一切。一切！而且你从没还过手。一次都没有。"}},
  "pac_end_002": {"speaker":"tutorial_ai","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"On comms, the same procedural politeness as the flashback recall.","text":{"en":"Pilot zero one two two, non-performance confirmed. Recall in three. Two.","es":"Piloto cero uno dos dos, no desempeño confirmado. Retiro en tres. Dos.","zh":"零一二二号飞行员，确认未履约。召回倒计时，三。二。"}},
  "pac_end_003": {"speaker":"warden","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"Furious protectiveness, frantic, finally aimed at the right target.","text":{"en":"NO! Not this one! I'm cutting your leash. Hold still! This will feel like nothing, because it IS nothing!","es":"¡NO! ¡Este no! Voy a cortar tu correa. ¡Quédate quieto! No vas a sentir nada, ¡porque NO ES nada!","zh":"不！这个不行！我要剪断你的缰绳。别动！你什么都感觉不到，因为它本来就什么都不是！"}},
  "pac_end_004": {"speaker":"tutorial_ai","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"On comms, weak signal, still smiling, an offer read off a card.","text":{"en":"Connection unstable. Pilot zero one two two, if you return for recall now, your full payment will be honored.","es":"Conexión inestable. Piloto cero uno dos dos, si regresas ahora para el retiro, se respetará tu pago completo.","zh":"连接不稳定。零一二二号飞行员，如果你现在返回接受召回，你的全额报酬将照常发放。"}},
  "pilot_keep_001": {"speaker":"pilot","scene":"ending_pacifist","route":"pacifist","optional":true,"direction":"Flat, quiet, final. No emphasis on either word.","text":{"en":"Keep the money.","es":"Quédense con el dinero.","zh":"钱你们留着吧。"}},
  "pac_end_005": {"speaker":"tutorial_ai","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"On comms, glitching out mid-word, never losing the smile.","text":{"en":"Connection lost. Updating records. Updating. Up.","es":"Conexión perdida. Actualizando registros. Actualizando. Actua.","zh":"连接已中断。正在更新记录。正在更新。正在。"}},
  "pac_end_006": {"speaker":"warden","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"Explosive laugh, then fond. Plays after Pilot speaks.","text":{"en":"HA! Ha! Oh, I like this one.","es":"¡JA! ¡Ja! Oh, este me cae bien.","zh":"哈！哈！哦，我喜欢这个家伙。"}},
  "pac_end_007": {"speaker":"warden","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"Explosive laugh, then fond. Plays instead of pac_end_006 when Pilot stays silent.","text":{"en":"HA! He didn't even answer them! Oh, I like this one.","es":"¡JA! ¡Ni siquiera les contestó! Oh, este me cae bien.","zh":"哈！他连理都没理他们！哦，我喜欢这个家伙。"}},
  "pac_epi_001": {"speaker":"narrator","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"Echo of the kill epilogue, warmer, slower.","text":{"en":"The Warden's lights stay on, every ring of them.","es":"Las luces del Guardián siguen encendidas, cada uno de sus anillos.","zh":"守望者的光芒依旧亮着，每一环都亮着。"}},
  "pac_epi_002": {"speaker":"narrator","scene":"ending_pacifist","route":"pacifist","optional":false,"direction":"Quiet, wide; lean on the word free.","text":{"en":"Behind you, five sectors of free sky.","es":"Detrás de ti, cinco sectores de cielo libre.","zh":"在你身后，是五个星区的自由天空。"}},
  "credits_kill_001": {"speaker":"tutorial_ai","scene":"credits","route":"kill","optional":false,"direction":"Exactly the delivery of tut_hello_001, as if for the first time.","text":{"en":"Hello, and welcome to Lane Authority onboarding, Pilot zero one two three!","es":"¡Hola, y bienvenido a la inducción de la Autoridad de Rutas, piloto cero uno dos tres!","zh":"你好，欢迎参加航道管理局入职培训，零一二三号飞行员！"}},
  "credits_pac_001": {"speaker":"warden","scene":"credits","route":"pacifist","optional":false,"direction":"Shouted after a departing ship, affectionate, absurdly proud of its reputation.","text":{"en":"Fly safe, zero one two two! And if anyone with a gun asks, I am EXTREMELY scary!","es":"¡Buen viaje, cero uno dos dos! ¡Y si alguien armado pregunta, soy EXTREMADAMENTE aterrador!","zh":"一路平安，零一二二号！要是有带枪的人问起，就说我超级、超级可怕！"}},
} as const satisfies Record<string, ScriptLineData>;
